    nodes: [['app', '写入应用', 'POST /orders/_doc', 'Send', 'blue'], ['coord', '协调节点', '算路由 · 广播合并', 'Route', 'blue'], ['primary', '主分片', 'P0 / P1 / P2 接收写入', 'Database', 'green'], ['replica', '副本分片', 'R0 / R1 / R2 随时接管', 'Server', 'pink'], ['idx', '索引 orders', '主分片数创建即定', 'Layers', 'yellow'], ['cluster', '集群', 'green / yellow / red', 'Activity', 'green']],
    edges: [['app', 'coord', '写入 / 查询'], ['coord', 'primary', 'hash(routing) % 3'], ['primary', 'replica', '副本同步'], ['replica', 'primary', '故障时提升'], ['idx', 'cluster', '分片状态上报'], ['primary', 'idx', '文档归属分片']],
    code: ['PUT /orders/_doc/1001                  // 路由：hash(_id) % 3 → 写入 P2', 'GET /_cat/shards/orders                 // 看 3 主 3 副如何散布在节点上', 'PUT /orders/_settings { "number_of_shards": 5 }  // 400！主分片数一经创建不可修改', '// 横向扩容正道：新索引 + reindex + 别名切换（短暂只读窗口）', 'POST /_reindex { "source": { "index": "orders" }, "dest": { "index": "orders-v2" } }', 'GET /_cluster/health                    // green 主副齐 / yellow 缺副本 / red 缺主', '// 脑裂防护：过半 quorum 才有资格当主', 'discovery.zen.minimum_master_nodes: 2   // 3 个 master 节点 → 至少 2 票'],
    theory: [['分片路由', 'hash(routing) % 主分片数', '写入与查询都先算路由：同一 _id 的文档永远落到同一个主分片，更新与读取只打一个分片；主分片数决定「桶」的数量，所以在建索引时就要按峰值流量估算好。'], ['副本与颜色', 'green / yellow / red', '每个主分片带 1+ 副本（分布在别的节点）。主分片丢 = red（读写受阻）；副本不足 = yellow（能读写但容灾降级）；全齐 = green。主节点宕机后，含最新数据的副本自动提升为新主，秒级到分钟级自愈。'], ['扩容与脑裂', 'reindex · 过半 quorum', '主分片数不可动态调大（改了路由哈希就全错位）——扩容量只能建新索引 reindex 搬数据再切别名。脑裂靠过半票数防：3 个 master 节点要求至少 2 票才允许选主，被分区孤立的单节点凑不齐 quorum 就自动降级，杜绝双主。']],
    goals: ['用 hash(routing) % 主分片数解释文档落位，说出为什么主分片数一经创建不可修改', '描述主分片所在节点宕机后的完整自愈流程：副本提升 → 补副本 → 恢复 green', '说出横向扩容的标准动作（新索引 + reindex + 别名切换）与过半 quorum 如何阻止脑裂'],
    challenge: { task: '固定 3 数据节点拓扑（N1: P0+R1 · N2: P1+R2 · N3: P2+R0），三个场景各运行一次：① 依次写入 #1001/#1002/#1003 三篇文档并各自完成副本同步 ② 宕掉 N2 观察 P1 主分片失联、R1 副本提升为新主、补副本后恢复 green、期间写入一笔恢复业务、N2 回归追平 ③ 演示对 orders 调大主分片数被 400 拒绝，改用 orders-v2 + reindex 扩容，再让 N2 与集群网络分区、观察它因凑不齐过半 quorum 而自动降级、恢复后重新归队。期望：① 写入 3 · 同步 3 · 零提升零迁移：三篇散落 P2/P0/P1 且全部完成主副同步 ② 写入 1 · 同步 2 · 提升 1 · 零迁移：看到 N2 变 DOWN、提升徽章、集群从 red 回到 green ③ 写入 0 · 同步 0 · 零提升 · 迁移 2：先看到 400 拒绝，再看 N2 变 SPLIT（孤岛降级）后恢复 UP。', hint: '看节点 token 颜色与 mono 主分片分配行：N2 变粉即宕机、变黄即分区；「提升」徽章出现代表副本接管；主分片分配行里 P1@N2 变为 P1↑@N1 即转移完成；scale 场景的 400 报错帧与 reindex 迁移 token 是关键确认点。', success: '能解释文档路由为什么永远打同一主分片、主分片数为何建索引时定死；能说清副本提升与集群颜色自愈的全过程；能说出扩容走 reindex、过半 quorum 防脑裂的机理。', requirements: [{ id: 'route', label: '① 分片路由 · hash 落位', when: { scenario: 'route' } }, { id: 'failover', label: '② 副本提升 · 故障转移', when: { scenario: 'failover' } }, { id: 'scale', label: '③ 扩容 reindex · 脑裂防护', when: { scenario: 'scale' } }] },
    quiz: [
      { prompt: '一篇文档写进 ES 后落在哪个主分片，由什么决定？', choices: ['协调节点随机挑一个负载最低的主分片', 'routing 值取哈希后再对主分片数取模——同一文档永远落同一分片', '按文档 _id 的字典序从小到大依次填充分片'], answer: 1, explanation: '路由规则是 hash(routing) % 主分片数：同一 routing 的文档恒定落在同一主分片，更新与查询只打一个分片。也因此主分片数一旦创建就不能改——改了取模结果全变，数据等于全部错位。' },
      { prompt: '主分片所在节点宕机，集群如何恢复可用？', choices: ['数据直接丢失，必须人工从备份恢复', '该分片的最新副本自动提升为新主分片，随后自动补建副本、颜色回到 green', '整个索引下线，直到宕机节点重新上线', '该分片永久降级为只读'], answer: 1, explanation: '副本不是冷备份而是随时可接管的活副本：主分片失联后，含最新数据的副本自动提升为新主，集群从 red 短暂变 yellow（缺副本），自动补建副本后回到 green——秒级到分钟级自愈，数据零丢失。' },
      { prompt: '索引建成后才发现主分片数不够、需要扩容，正确做法是？', choices: ['直接调大 number_of_shards 设置，分片自动分裂', '停掉索引后重建，旧数据废弃', '建一个更多主分片的新索引，reindex 搬数据，别名切换后删旧索引'], answer: 2, explanation: '主分片数被路由哈希锁死，不能原地改；扩容正道是建新索引（按峰值流量定分片数）→ reindex 后台搬数据 → 别名原子切换 → 删旧索引，业务只经历短暂只读窗口。' },
    ],
    boundary: '固定 3 节点 + 3 主分片的教学拓扑，路由哈希与文档标号为示意（未模拟真实 Murmur3 路由、自定义 routing 参数与 shard_size）；未模拟分片分配策略（磁盘水印/节点 awareness）、translog/flush 与副本同步内部机制、zen/fang 一致性协议的交互细节、集群 reroute 手工迁移、滚动升级与重启顺序、ILM 生命周期；集群颜色变化与提升耗时按教学节奏推进，副本同步次数为教学计数。',
    source: 'https://www.elastic.co/guide/en/elasticsearch/reference/current/scalability.html',
